source.loginUrl:
function login(){}
function male(key){
	java.put("pd","male");
	java.toast('已切换至♂男频发现');
	}
function female(){
	java.put("pd","female");
	java.toast('已切换至♀女频发现');
	}
function Login(){	java.startBrowserAwait('http://111.170.19.23:49998/my.html', "获取Token");
	}

function saveToken(v) {
  let token = v || result['Token']
  if (String(token).length <= 30) {
    java.toast('请输入有效token')
  } else {
  	url=`{{h}}/ceshi.php?tokens=${token}`
    let res = java.ajax(url)
    let data = JSON.parse(res)
    //java.log(JSON.stringify(data))
    if (data.code==200) {
      source.put('token', token)
      java.longToast(`\n✅查询成功\n用户：${data.data.username}${data.data.daily_limit ? `\n日下载限制：${data.data.daily_limit}` : ''}\n日下载剩余：${data.data.else}`);
 source.putLoginInfo(JSON.stringify(result))
    } else {
      java.longToast('\n❌查询失败\n' + data.error)
    }
  }
}

